        if (r[0] === "rice" && c.step !== "prep" && c.step !== "proc") { const w = GK.water(11, 7.5, 0x5a7a6a, 0.55); w.position.y = 0.06; g.add(w); }
        if (c.step === "prep") { AK.field(g, "weed", { x0: -5, x1: 5, z0: -3.4, z1: 3.4, dx: 0.5, dz: 0.5, s: 0.8, h }); const tr = AK.tractor(); AK.put(g, tr, -2, 0, h, 0, 0.55); tr.add((() => { const o = AK.implement("disc"); o.position.set(-1.3, 0, 0); return o; })()); AK.put(g, AK.person(), 2, 1.5, h, 0, 0.6); const cut = AK.tool("cutlass"); cut.scale.setScalar(1.2); AK.put(g, cut, 2.3, 1.2, h); }
