    update(S, s, c) { const H = MK.scenes["D3-g"].grass(c), k = H.map(Math.round).join("|") + c.mode + c.herd + Math.floor(c.day / 7); if (s.key === k) return; s.key = k; const g = BK.group(S, s), h = AK.ground(g, { w: 12, d: 8, amp: 0.02 }); const cur = Math.floor(c.day / 7) % 4; [[-2.8, -1.8], [2.8, -1.8], [-2.8, 1.8], [2.8, 1.8]].forEach(([x, z], p) => { g.add(AK.fence([[x - 2.5, z - 1.6], [x + 2.5, z - 1.6], [x + 2.5, z + 1.6], [x - 2.5, z + 1.6], [x - 2.5, z - 1.6]], 0.4)); AK.field(g, "guinea", { x0: x - 2.2, x1: x + 2.2, z0: z - 1.3, z1: z + 1.3, dx: 0.45, dz: 0.45, s: 0.04 + H[p] / 40 * 0.42, stage: 0.4 + H[p] / 80, h }); const here = c.mode === "cont" ? Math.round(c.herd / 4) : p === cur ? c.herd : 0; for (let i = 0; i < here; i++) AK.put(g, AK.animal(i % 2 ? "ndama" : "whitefulani"), x - 1.8 + (i % 5) * 0.9, z - 0.8 + Math.floor(i / 5) * 0.6, h, i, 0.32); }); },
    hud: (s, c) => { const H = MK.scenes["D3-g"].grass(c), avg = H.reduce((a, b) => a + b) / 4; return [{ title: "Day " + c.day + " — average grass height " + f(avg, 3) + " cm", lines: [["Paddocks: " + H.map((v) => Math.round(v) + " cm").join(" · "), "#ffd27a", true], "Management: rotational or controlled grazing, correct stocking rate, fertilizer, weeding, reseeding, irrigation, controlled burning, pest control."] }]; },
